import { expect, expectStatus, test, uniqueName, USERS, type APIRequestContext, type Persona } from "../../fixtures";

const SUFFIX = () => `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

/** Finds a seeded persona that belongs to the Globex Procurement tenant. */
async function globexPersona(apiAs: (p: Persona) => Promise<APIRequestContext>): Promise<Persona> {
  for (const persona of Object.keys(USERS) as Persona[]) {
    const client = await apiAs(persona);
    const response = await client.get("/api/me");
    if (!response.ok()) continue;
    const profile = (await response.json()) as { tenant?: { name?: string } };
    if (profile.tenant?.name === "Globex Procurement") return persona;
  }
  throw new Error("No seeded persona belongs to tenant 'Globex Procurement'");
}

test.describe("vendor audit trail tenant isolation", () => {
  test(
    "audit trails from another tenant are invisible",
    { tag: "@AUD-02" },
    async ({ apiAs }) => {
      // Arrange: a signed-in member of Northwind Supply
      const member = await apiAs("member");

      // Arrange: a vendor that exists in tenant Globex Procurement
      const globex = await apiAs(await globexPersona(apiAs));
      const suffix = SUFFIX();
      const created = await globex.post("/api/vendors", {
        data: {
          name: uniqueName(`Globex Vendor ${suffix}`),
          category: "software",
          contact_email: `vendor-${suffix}@globex.test`,
        },
      });
      const vendor = await expectStatus<{ id: string }>(created, 201);
      expect(vendor.id).toBeTruthy();

      // Act: the Northwind member requests the Globex vendor's audit trail
      const response = await member.get(`/api/vendors/${vendor.id}/audit`);

      // Assert
      await expectStatus(response, 404);
    },
  );
});
